package cc.echomusic.android;

import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;

final class TvFocus {
    static void install(View root){if(!BuildConfig.TV||Boolean.TRUE.equals(root.getTag(R.id.tv_focus_root)))return;root.setTag(R.id.tv_focus_root,true);scan(root);root.getViewTreeObserver().addOnGlobalLayoutListener(()->scan(root));root.post(()->{if(root.findFocus()==null)first(root);});}
    private static boolean first(View view){if(view.isFocusable()&&view.isEnabled()&&view.getVisibility()==View.VISIBLE&&!(view instanceof android.view.ViewGroup)){view.requestFocus();return true;}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)if(first(group.getChildAt(i)))return true;}return false;}
    static String focusedLabel(View root){View focused=root==null?null:root.findFocus();if(focused instanceof TextView)return ((TextView)focused).getText().toString();return focused==null||focused.getContentDescription()==null?"":focused.getContentDescription().toString();}
    static void restore(View root,String label){if(label.isEmpty())return;root.post(()->restoreNow(root,label));}
    private static boolean restoreNow(View view,String label){String value=view instanceof TextView?((TextView)view).getText().toString():view.getContentDescription()==null?"":view.getContentDescription().toString();if(view.isFocusable()&&view.isEnabled()&&label.equals(value)){view.requestFocus();return true;}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)if(restoreNow(group.getChildAt(i),label))return true;}return false;}
    private static void scan(View view){if(view instanceof ListView){ListView list=(ListView)view;if(!Boolean.TRUE.equals(list.getTag(R.id.tv_focus_item))){list.setTag(R.id.tv_focus_item,true);StateListDrawable selector=new StateListDrawable();GradientDrawable highlight=new GradientDrawable();highlight.setColor(0xff8fdde5);highlight.setCornerRadius(12);highlight.setStroke(4,0xff07515d);selector.addState(new int[]{android.R.attr.state_focused,android.R.attr.state_window_focused},highlight);selector.addState(new int[]{},new ColorDrawable(android.graphics.Color.TRANSPARENT));list.setSelector(selector);}list.setItemsCanFocus(false);list.setDescendantFocusability(android.view.ViewGroup.FOCUS_BLOCK_DESCENDANTS);list.setFocusable(true);return;}if(view.isClickable()&&view.isEnabled()&&!Boolean.TRUE.equals(view.getTag(R.id.tv_focus_item))){view.setTag(R.id.tv_focus_item,true);view.setFocusable(true);view.setFocusableInTouchMode(false);android.graphics.drawable.Drawable original=view.getBackground();android.content.res.ColorStateList color=view instanceof TextView?((TextView)view).getTextColors():null;view.setOnFocusChangeListener((v,focused)->{if(focused){GradientDrawable highlight=new GradientDrawable();highlight.setColor(0xff28576b);highlight.setCornerRadius(12);highlight.setStroke(3,0xffa5f2f3);v.setBackground(highlight);if(v instanceof TextView)((TextView)v).setTextColor(0xffffffff);}else{v.setBackground(original);if(v instanceof TextView)((TextView)v).setTextColor(color);}});}
        if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)scan(group.getChildAt(i));}}
}
